pub fn enterBlock(self: *HtmlRenderer, block_type: BlockType, data: u32, flags: u32) void {
            switch (block_type) {
.doc => {

},
.quote => {
_ = self.ensureNewline();
            _ = self.write("<blockquote>\n");
},
.ul => {
_ = self.ensureNewline();
            _ = self.write("<ul>\n");
},
.ol => {
_ = self.ensureNewline();
            const start = data;
            if ((start == 1)) {
                _ = self.write("<ol>\n");
            } else {
                _ = self.write("<ol start=\"");
                _ = self.writeDecimal(start);
                _ = self.write("\">\n");
            }
},
.li => {
const task_mark = types.taskMarkFromData(data);
            if ((task_mark != 0)) {
                _ = self.write("<li class=\"task-list-item\">");
                if (types.isTaskChecked(task_mark)) {
                    _ = self.write("<input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled checked>");
                } else {
                    _ = self.write("<input type=\"checkbox\" class=\"task-list-item-checkbox\" disabled>");
                }
            } else {
                _ = self.write("<li>");
            }
},
.hr => {
_ = self.ensureNewline();
            _ = self.write("<hr />\n");
},
.h => {
_ = self.ensureNewline();
            if (self.heading_tracker.enabled) {
                _ = self.heading_tracker.enterHeading();
            } else {
                const level = data;
                const tag = (switch (level) {
1 => "<h1>",
2 => "<h2>",
3 => "<h3>",
4 => "<h4>",
5 => "<h5>",
else => "<h6>",
});
                _ = self.write(tag);
            }
},
.code => {
_ = self.ensureNewline();
            _ = self.write("<pre><code");
            if (((flags & types.BLOCK_FENCED_CODE) != 0)) {
                const info_beg = data;
                var lang_end = info_beg;
                _ = &lang_end;
                while ((((lang_end < self.src_text.len) and (!helpers.isBlank(self.src_text[@as(usize, @intCast(lang_end))]))) and (!helpers.isNewline(self.src_text[@as(usize, @intCast(lang_end))])))) {
                    lang_end = (lang_end + 1);
                }
                if ((lang_end > info_beg)) {
                    _ = self.write(" class=\"language-");
                    _ = self.writeWithEntityDecoding(self.src_text[info_beg..lang_end]);
                    _ = self.write("\"");
                }
            }
            _ = self.write(">");
},
.html => {
_ = self.ensureNewline();
},
.p => {
_ = self.ensureNewline();
            _ = self.write("<p>");
},
.table => {
_ = self.ensureNewline();
            _ = self.write("<table>\n");
},
.thead => {
_ = self.write("<thead>\n");
},
.tbody => {
_ = self.write("<tbody>\n");
},
.tr => {
_ = self.write("<tr>");
},
.th, .td => {
const tag = (if ((block_type == .th)) "<th" else "<td");
            _ = self.write(tag);
            const alignment = types.alignmentFromData(data);
            if (types.alignmentName(alignment)) |name| {
                _ = &name;
                _ = self.write(" align=\"");
                _ = self.write(name);
                _ = self.write("\"");
            }
            _ = self.write(">");
},
}
    }

pub fn leaveBlock(self: *HtmlRenderer, block_type: BlockType, data: u32) void {
            switch (block_type) {
.doc => {

},
.quote => {
_ = self.write("</blockquote>\n");
},
.ul => {
_ = self.write("</ul>\n");
},
.ol => {
_ = self.write("</ol>\n");
